SELECT DISTINCT ?item ?matchedLabel ?en ?zh ?description ?kind WHERE {
          VALUES ?matchedLabel { "Bayesian network"@en "F1 score"@en "area under the curve"@en "automatic differentiation"@en "autoregressive model"@en "bayesian network"@en "benchmark"@en "branch"@en "breakpoint"@en "class imbalance"@en "classification"@en "clustering"@en "commit"@en "computational graph"@en "confusion matrix"@en "continuous delivery"@en "continuous integration"@en "coupling"@en "cross-validation"@en "data augmentation"@en "data parallelism"@en "debugging"@en "decision tree"@en "decoder"@en "dependency injection"@en "design pattern"@en "diffusion model"@en "discriminative model"@en "distributed training"@en "embedding"@en "encoder"@en "end-to-end test"@en "f1 score"@en "fine-tuning"@en "generative adversarial network"@en "generative model"@en "in-context learning"@en "inference"@en "information retrieval"@en "integration test"@en "inversion of control"@en "knowledge distillation"@en "language model"@en "large language model"@en "logging"@en "machine translation"@en "merge"@en "mixed precision"@en "model compression"@en "model parallelism"@en "multi-head attention"@en "named entity recognition"@en "natural language processing"@en "nearest neighbor"@en "pipeline parallelism"@en "positional encoding"@en "precision"@en "principal component analysis"@en "profiling"@en "prompt"@en "pruning"@en "pull request"@en "quantization"@en "random forest"@en "recall"@en "receiver operating characteristic"@en "refactoring"@en "regression"@en "regression test"@en "repository"@en "retrieval-augmented generation"@en "separation of concerns"@en "software engineering"@en "support vector machine"@en "technical debt"@en "tensor"@en "test coverage"@en "tokenization"@en "transformer"@en "unit test"@en "variational autoencoder"@en "version control"@en }
          ?item (rdfs:label|skos:altLabel) ?matchedLabel.
          OPTIONAL { ?item rdfs:label ?en. FILTER(LANG(?en)="en") }
          OPTIONAL { ?item rdfs:label ?zh. FILTER(LANG(?zh) IN ("zh-hans","zh-cn","zh")) }
          OPTIONAL { ?item schema:description ?description. FILTER(LANG(?description)="en") }
          OPTIONAL { ?item wdt:P31 ?kind }
        }
